#pragma once
// Palette entries for the physical animation nodes (docs/physics/PHYSICAL_ANIMATION.md). NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after pin()/attr() are
// defined, and calls appendPhysAnimNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphPhysAnimNodeTable.cs pin for pin. Bones and the profile are node attributes, not pins. The
// impulse is world space in kg*cm/s (about 3000 is a full reaction with the default profile); point and radius only matter for a
// radial event (radius > 0). Get Physical Animation State reads life (0 Alive, 1 Dying, 2 Dead, 3 GettingUp) and facing (0 Upright,
// 1 Supine, 2 Prone, 3 Side).

inline void appendPhysAnimNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"ApplyHitReaction", "Apply Hit Reaction", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("px", "float", false), pin("py", "float", false), pin("pz", "float", false), pin("damage", "float", false), pin("radius", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)},
        {attr("bone", "Bone hit (empty = root part)")}});
    t.push_back({"SetPhysicalAnimationProfile", "Set Physical Animation Profile", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("profile", "Profile (.ocphysanim, empty = defaults)")}});
    t.push_back({"BlendPhysicalAnimation", "Blend Physical Animation", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("weight", "float", false), pin("seconds", "float", false, "0.2"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"SimulateBoneSubtree", "Simulate Bone Subtree", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("bone", "Bone (empty = whole body)")}});
    t.push_back({"SetBoneStrength", "Set Bone Strength", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("strength", "float", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("bone", "Bone")}});
    t.push_back({"SetBoneBlend", "Set Bone Blend", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("blend", "float", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("bone", "Bone")}});
    t.push_back({"PinBone", "Pin Bone", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("pinned", "bool", false, "true"), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("bone", "Bone")}});
    t.push_back({"DieAsRagdoll", "Die As Ragdoll", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"GetUpFromRagdoll", "Get Up From Ragdoll", "Animation", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"GetPhysicalAnimationState", "Get Physical Animation State", "Animation", {
        pin("entity", "int", false), pin("found", "bool", true), pin("life", "int", true), pin("facing", "int", true), pin("reacting", "int", true)}});
}
